-- Ultimo = la linea con FechaInicio mas reciente de cada telar (en local la de 401 no era la ultima).
UPDATE p SET Ultimo = CASE WHEN p.Id = (SELECT TOP 1 x.Id FROM dbo.ReqProgramaTejido x
        WHERE x.SalonTejidoId IN ('KARL MAYER','KM') AND x.NoTelarId = p.NoTelarId ORDER BY x.FechaInicio DESC, x.Id DESC)
    THEN '1' ELSE '0' END
FROM dbo.ReqProgramaTejido p
WHERE p.SalonTejidoId IN ('KARL MAYER','KM') AND p.NoTelarId IN ('401','402');

-- Revisar: deben salir las lineas EnProceso de 401 y 402.
SELECT Id, NoTelarId, NoProduccion, NombreProducto, SaldoPedido, HorasProd, FechaInicio, FechaFinal, EnProceso, Ultimo
FROM dbo.ReqProgramaTejido WHERE SalonTejidoId IN ('KARL MAYER','KM') AND NoTelarId IN ('401','402') AND EnProceso = 1;

